package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService implements OrderFacade {

    private static final long WHOLE_RATE = 10_000; // 100% in basis points

    private final OrderRepository orders;

    public OrderService(OrderRepository orders) {
        this.orders = orders;
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    @Override
    @Transactional
    public void confirm(String orderId) {
        orders.get(orderId).changeStatus("CONFIRMED");
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional
    public void applyDiscount(String orderId, String percent) {
        long rate = parseBasisPoints(percent);
        Order order = orders.get(orderId);
        Money total = order.total();
        long discount = roundHalfUp(total.minorUnits() * rate, WHOLE_RATE);
        order.changeTotal(new Money(total.minorUnits() - discount, total.currency()));
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status());
    }

    /** Converts text such as "12.5" or "12.50" to basis points (1250), without floating point. */
    static long parseBasisPoints(String text) {
        if (null == text) {
            throw new ShopProblem("invalid-percent", "Percent is missing");
        }
        String s = text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);
        if (!isDigits(whole) || (dot >= 0 && (fraction.length() < 1 || fraction.length() > 2 || !isDigits(fraction)))) {
            throw new ShopProblem("invalid-percent", "Not a percentage with at most two decimals: " + text);
        }
        if (whole.length() > 9) {
            throw new ShopProblem("percent-out-of-range", "Percent must be between 0 and 100: " + text);
        }
        long basisPoints = Long.parseLong(whole) * 100;
        if (dot >= 0) {
            basisPoints += Long.parseLong(fraction) * (fraction.length() == 1 ? 10 : 1);
        }
        if (basisPoints > WHOLE_RATE) {
            throw new ShopProblem("percent-out-of-range", "Percent must be between 0 and 100: " + text);
        }
        return basisPoints;
    }

    /** Divides by a positive divisor, rounding half up (towards positive infinity). */
    static long roundHalfUp(long numerator, long divisor) {
        return Math.floorDiv(2 * numerator + divisor, 2 * divisor);
    }

    private static boolean isDigits(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }
}
